static int cg(void *ctx,SatchelCPUProbe *cpu,uint64_t a,uint64_t n){Fixture *f=ctx;return no_device(f,cpu,a,n)&&(!f->textures || satchel_guest_textures_pool_guard(f->textures,cpu,a,n)==SATCHEL_GTEX_OK);}
