typedef struct {Fixture *fixture;unsigned calls;} MutatingCancel;
static int mutating_cancel(void *p){MutatingCancel *m=p;if(++m->calls==3){uint8_t value=0xff;CHECK(satchel_cpu_probe_write(m->fixture->cpu,STORAGE+0x90,&value,1));pool(m->fixture,SATCHEL_GUEST_POOL_FLUSH,0x90,1,SATCHEL_GUEST_POOL_OK);}return 0;}
static int cancelled(void *p){(void)p;return 1;}
static uint32_t begin(Fixture *f,SatchelGuestRasterRequest *r,SatchelGuestRasterRun **run){return satchel_guest_raster_run_begin(f->pools,f->textures,f->programs,f->cpu,r,run,NULL,NULL);}
